/* Arbitrary value: exactly the CSS gradient, any Tailwind v4 project. */
bg-[linear-gradient(270deg,rgb(51_102_153_/_0.5),rgb(153_204_51_/_0.5))]

/* Native utilities (two or three stops). bg-linear-<angle> interpolates in OKLAB by default in Tailwind v4; the modifier pins the space. */
bg-linear-270/srgb from-[rgb(51_102_153_/_0.5)] to-[rgb(153_204_51_/_0.5)]

/* Theme variable: use as class "bg-gradient". */
@theme {
  --background-image-gradient: linear-gradient(270deg, rgb(51 102 153 / 0.5), rgb(153 204 51 / 0.5));
}

/* Custom utility: use as class "bg-gradient". */
@utility bg-gradient {
  background-image: linear-gradient(270deg, rgb(51 102 153 / 0.5), rgb(153 204 51 / 0.5));
}

css-variables:
:root {
  --gradient-angle: 270deg;
  --gradient-color-1: rgb(51 102 153 / 0.5);
  --gradient-color-2: rgb(153 204 51 / 0.5);
  --gradient: linear-gradient(var(--gradient-angle), var(--gradient-color-1), var(--gradient-color-2));
}

/* Usage: background: var(--gradient); */

